import * as Organisation from '../models/organisation.js';
import { sendToApi } from '../models/send-to-api.js';
import { styleText } from './style-text.js';

export const OAUTH_CONSUMER_RIGHTS = [
  'access_organisations',
  'access_organisations_bills',
  'access_organisations_consumption_statistics',
  'access_organisations_credit_count',
  'access_personal_information',
  'manage_organisations',
  'manage_organisations_applications',
  'manage_organisations_members',
  'manage_organisations_services',
  'manage_personal_information',
  'manage_ssh_keys',
];

/**
 * Get the owner params expected by the OAuth consumer endpoints: no ID targets the current user
 * @param {{ orga_id?: string, orga_name?: string }} [orgIdOrName]
 * @returns {Promise<{ id?: string }>}
 */
export async function getOwnerParams(orgIdOrName) {
  const id = await Organisation.getId(orgIdOrName);
  return id != null ? { id } : {};
}

/**
 * Build the rights object expected by the API from a list of enabled rights
 * @param {Array<string>} enabledRights
 * @returns {Record<string, boolean>}
 */
export function toRightsObject(enabledRights) {
  return Object.fromEntries(OAUTH_CONSUMER_RIGHTS.map((right) => [right, enabledRights.includes(right)]));
}

/**
 * List the rights enabled in a rights object returned by the API
 * @param {Record<string, boolean>} [rights]
 * @returns {Array<string>}
 */
export function getEnabledRights(rights) {
  return Object.entries(rights ?? {})
    .filter(([_, isEnabled]) => isEnabled)
    .map(([right]) => right);
}

/**
 * Find an OAuth consumer by its key or name
 * @param {{ id?: string }} ownerParams
 * @param {string} keyOrName
 * @throws {Error} if no consumer or several consumers are found
 * @returns {Promise<Object>} The OAuth consumer
 */
export async function findOauthConsumer(ownerParams, keyOrName) {
  const consumers = await getAll(ownerParams).then(sendToApi);

  const consumerByKey = consumers.find((consumer) => consumer.key === keyOrName);
  if (consumerByKey != null) {
    return consumerByKey;
  }

  const consumersByName = consumers.filter((consumer) => consumer.name === keyOrName);
  if (consumersByName.length === 0) {
    throw new Error(`OAuth consumer ${styleText('red', keyOrName)} not found`);
  }
  if (consumersByName.length > 1) {
    throw new Error(
      `Several OAuth consumers are named ${styleText('red', keyOrName)}, use its key instead: ${consumersByName.map((consumer) => consumer.key).join(', ')}`,
    );
  }
  return consumersByName[0];
}

/**
 * Get the Console path of an OAuth consumer
 * @param {{ id?: string }} ownerParams
 * @param {string} consumerKey
 * @returns {string}
 */
export function getOauthConsumerConsolePath(ownerParams, consumerKey) {
  const prefixPath = ownerParams.id != null ? `organisations/${ownerParams.id}` : 'users/me';
  return `/${prefixPath}/oauth-consumers/${consumerKey}`;
}
